import {t, language, eventLabel, applyTranslations, addLanguagePicker, localizedError, errorText} from './i18n.js';
const $=id=>document.getElementById(id);let file=null,objectURL=null,upload=null,job=null,timer=null,detections=[],session=null,picking=false;
async function json(path,body){const r=await fetch(path,body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{});const data=await r.json();if(!r.ok)throw localizedError('error.request',{status:r.status});return data;}
function config(){return JSON.parse($('config').value);}
function saveConfig(value){$('config').value=JSON.stringify(value,null,2);$('point-status').textContent=t('sources.points',{count:value.image_points?.length||0});}
$('import').onclick=async()=>{try{const selected=$('events').files[0];if(!selected)throw localizedError('error.choose_events');if(selected.size>20_000_000)throw localizedError('error.events_large');const text=await selected.text();const rows=text.trim().startsWith('[')?JSON.parse(text):text.split(/\r?\n/).filter(l=>l.trim()).map(l=>JSON.parse(l));const result=await json('/api/session',{records:rows,preferences:{language:language()}});location.href=`./?session=${result.session_id}&lang=${language()}`;}catch(e){$('import-status').textContent=errorText(e);}};
$('file').onchange=()=>{file=$('file').files[0];if(!file)return;if(objectURL)URL.revokeObjectURL(objectURL);objectURL=URL.createObjectURL(file);$('preview').src=objectURL;upload=null;session=null;job=null;detections=[];$('run').disabled=false;$('result').hidden=true;$('status').textContent=t('sources.loaded');};
$('preview').onloadedmetadata=()=>{$('anchors').width=$('preview').videoWidth;$('anchors').height=$('preview').videoHeight;};
$('pick').onclick=()=>{if(!file)return;$('preview').pause();$('preview').currentTime=0;picking=true;document.querySelector('.preview').classList.add('picking');$('point-status').textContent=t('sources.click_point');};
$('anchors').onclick=e=>{if(!picking)return;const rect=$('anchors').getBoundingClientRect(),x=(e.clientX-rect.left)/rect.width*$('anchors').width,y=(e.clientY-rect.top)/rect.height*$('anchors').height;try{const c=config();c.auto_pitch=false;$('auto-pitch').checked=false;c.image_points??=[];c.pitch_points??=[];c.image_points.push([Math.round(x),Math.round(y)]);c.pitch_points.push([Number($('x').value),Number($('y').value)]);saveConfig(c);}catch(e){$('status').textContent=errorText(e);}picking=false;document.querySelector('.preview').classList.remove('picking');};
$('auto-pitch').onchange=()=>{try{saveConfig({...config(),auto_pitch:$('auto-pitch').checked});}catch(e){$('status').textContent=errorText(e);}};
$('clear').onclick=()=>{try{saveConfig({...config(),image_points:[],pitch_points:[]});}catch(e){$('status').textContent=errorText(e);}};
$('run').onclick=async()=>{try{if(!file)return;const c=config();if(c.image_points?.length&&c.image_points.length<4)throw localizedError('error.anchors');$('run').disabled=true;$('status').textContent=t('sources.uploading');if(!upload){const r=await fetch('/api/video/upload',{method:'POST',headers:{'Content-Type':'application/octet-stream'},body:file});const value=await r.json();if(!r.ok)throw localizedError('error.request',{status:r.status});upload=value.upload_id;}const created=await json('/api/video/start',{upload_id:upload,config:c});job=created.job_id;$('cancel').disabled=false;poll();}catch(e){$('status').textContent=errorText(e);$('run').disabled=false;}};
$('cancel').onclick=async()=>{try{if(job)await json('/api/video/cancel',{job_id:job});}catch(error){$('status').textContent=errorText(error);}};
async function poll(){try{const value=await json(`/api/video/status?job=${job}`),p=value.progress;$('progress').value=p.total_ms?100*p.processed_ms/p.total_ms:0;$('status').textContent=t('sources.progress',{status:t('job.'+value.status),frames:p.frames||0,events:p.events||0});
 if(['queued','running'].includes(value.status)){timer=setTimeout(poll,1000);return;}$('run').disabled=false;$('cancel').disabled=true;
 if(value.status!=='complete'){if(value.error)$('status').textContent=t('sources.failed');return;}
 $('progress').value=100;detections=await json(`/api/video/detections?job=${job}`);if(!session){const result=await json('/api/video/session',{job_id:job,preferences:{language:language()}});session=result.session_id;}else await json('/api/control',{session,preferences:{language:language()}});
 const s=value.summary;$('summary').textContent=JSON.stringify({[t('summary.status')]:t('job.'+s.status),[t('summary.frames')]:s.frames,[t('summary.detections')]:Object.fromEntries(Object.entries(s.detections).map(([kind,count])=>[eventLabel(kind),count])),[t('summary.events')]:s.events,[t('summary.elapsed')]:s.elapsed_seconds,[t('summary.calibrated')]:t(s.calibrated?'common.yes':'common.no'),[t('summary.calls')]:s.model_api_calls,[t('summary.method')]:t('summary.method_text')},null,2);
 $('links').replaceChildren(...[[`./?session=${session}&lang=${language()}`,t('sources.open')],[`./overlay.html?session=${session}&lang=${language()}`,t('sources.sync')]].map(([href,text])=>{const a=document.createElement('a');a.href=href;a.textContent=text;a.style.marginRight='20px';return a;}));$('result').hidden=false;
 }catch(e){$('status').textContent=errorText(e);$('run').disabled=false;$('cancel').disabled=true;}}
$('export').onclick=async()=>{try{const rows=await json(`/api/video/records?job=${job}`);const url=URL.createObjectURL(new Blob([rows.map(r=>JSON.stringify(r)).join('\n')+'\n'],{type:'application/x-ndjson'}));const a=document.createElement('a');a.href=url;a.download='matchlens-video-events.jsonl';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(e){$('status').textContent=errorText(e);}};
function draw(){const canvas=$('anchors'),ctx=canvas.getContext('2d');ctx.clearRect(0,0,canvas.width,canvas.height);
 try{if($('preview').currentTime<.15)(config().image_points||[]).forEach(([x,y],i)=>{ctx.fillStyle='#ff795b';ctx.beginPath();ctx.arc(x,y,9,0,Math.PI*2);ctx.fill();ctx.font='24px system-ui';ctx.fillText(String(i+1),x+12,y);});}catch{}
 const t=$('preview').currentTime*1000;let frame=null;for(const row of detections){if(row.time_ms>t)break;frame=row;}
 if(frame&&t-frame.time_ms<300)for(const d of frame.detections){if(d.confidence<.3)continue;const [x1,y1,x2,y2]=d.box;ctx.strokeStyle=d.class==='ball'?'#ffcb32':'#80ebcf';ctx.lineWidth=3;ctx.strokeRect(x1,y1,x2-x1,y2-y1);ctx.font='16px system-ui';ctx.fillStyle=ctx.strokeStyle;ctx.fillText(`${eventLabel(d.class)}${d.track?' #'+d.track:''}`,x1,y1-5);}
 requestAnimationFrame(draw);
}draw();

document.body.dataset.pageTitle='ui.sources';addLanguagePicker(document.querySelector('header'));applyTranslations();
document.addEventListener('matchlens:language',()=>{if(job){clearTimeout(timer);poll();}else $('status').textContent=t(file?'sources.loaded':'sources.initial');try{$('point-status').textContent=t('sources.points',{count:config().image_points?.length||0});}catch{}});
